        (0.0049, 0.9951, "0.5%", "99.5%"), (0.005, 0.995, "0.5%", "99.5%"), (0.0051, 0.9949, "0.5%", "99.5%"),
        (0.0449, 0.9551, "4.5%", "95.5%"), (0.05, 0.95, "5.0%", "95.0%"), (0.0995, 0.9005, "10.0%", "90.0%"),
        (0.1, 0.9, "10.0%", "90.0%"), (0.1234, 0.8766, "12.3%", "87.7%"), (0.25, 0.75, "25.0%", "75.0%"),
        (0.3675, 0.6325, "36.8%", "63.2%"), (0.45, 0.55, "45.0%", "55.0%"), (0.4995, 0.5005, "50.0%", "50.0%"),
        (0.5, 0.5, "50.0%", "50.0%"), (0.5005, 0.4995, "50.1%", "49.9%"), (0.523, 0.477, "52.3%", "47.7%"),
        (0.5235, 0.4765, "52.4%", "47.6%"), (0.55555, 0.44445, "55.6%", "44.4%"), (0.61949, 0.38051, "61.9%", "38.1%"),
        (0.7, 0.3, "70.0%", "30.0%"), (0.8765, 0.1235, "87.7%", "12.3%"), (0.9, 0.1, "90.0%", "10.0%"),
        (0.95, 0.05, "95.0%", "5.0%"), (0.9949, 0.0051, "99.5%", "0.5%"), (0.995, 0.005, "99.5%", "0.5%"),
        (0.9951, 0.0049, "99.5%", "0.5%"), (0.9955, 0.0045, ">99%", "<1%"), (0.9956, 0.0044, ">99%", "<1%"),
        (0.999, 0.001, ">99%", "<1%"), (1, 0, "100%", "0%"),
