    func testTheHeadlinePairPrintsTheWebsTenthForEveryCase() {
        for row in Self.web {
            let printed = EventHeadlineTenths10090.pair(home: row.home, away: row.away)
            XCTAssertEqual(printed.home, row.homeText, "home \(row.home)")
            XCTAssertEqual(printed.away, row.awayText, "away of \(row.home)")
        }
    }

    /// The away side is derived, never rounded on its own: every unbanded
    /// complement pair sums to exactly 100.0 across the whole range.
    func testEveryUnbandedComplementPairSumsToOneHundred() {
        var checked = 0
        for step in 50...9950 {
            let home = Double(step) / 10_000
            let away = ((1 - home) * 1_000_000).rounded() / 1_000_000
            let printed = EventHeadlineTenths10090.pair(home: home, away: away)
            guard let a = printed.away, let h = tenths(printed.home), let w = tenths(a) else {
                XCTAssertTrue(printed.home.hasPrefix("<") || printed.home.hasPrefix(">"), "\(home): \(printed)")
                continue
            }
            XCTAssertEqual(h + w, 1000, "home \(home) printed \(printed.home) / \(a)")
            checked += 1
        }
        XCTAssertGreaterThan(checked, 9_000)
    }

    /// The bands stay, symmetric about the pair, and never print a boundary
    /// the value is not on.
    func testTheBandsStayAndAreSymmetric() {
        XCTAssertEqual(EventHeadlineTenths10090.pair(home: 0.0044, away: 0.9956).home, "<1%")
        XCTAssertEqual(EventHeadlineTenths10090.pair(home: 0.0044, away: 0.9956).away, ">99%")
        XCTAssertEqual(EventHeadlineTenths10090.pair(home: 0.9956, away: 0.0044).home, ">99%")
        XCTAssertEqual(EventHeadlineTenths10090.pair(home: 0.9956, away: 0.0044).away, "<1%")
        // A possible value never reads as impossible, nor an open one as certain.
        XCTAssertEqual(EventHeadlineTenths10090.pair(home: 0.0001, away: nil).home, "<1%")
        XCTAssertEqual(EventHeadlineTenths10090.pair(home: 0.9999, away: nil).home, ">99%")
    }

    private func tenths(_ text: String) -> Int? {
        guard !text.hasPrefix("<"), !text.hasPrefix(">"), text.hasSuffix("%") else { return nil }
        let digits = text.dropLast().split(separator: ".")
        guard digits.count == 2, let whole = Int(digits[0]), let tenth = Int(digits[1]) else { return nil }
        return whole * 10 + tenth
    }

